parameters.jsCode:
const ragResponse = $node['RAG - Agentic Query'].json;
const webhookData = $node['Webhook - Question Input'].json;
const evalResponse = $node['RAGAS - Quality Evaluation']?.json;

return [{
  json: {
    question: webhookData.body?.question || webhookData.question,
    answer: ragResponse.answer,
    contexts: ragResponse.contexts || [],
    evaluation: evalResponse ? {
      faithfulness: evalResponse.faithfulness,
      answer_relevance: evalResponse.answer_relevance,
      context_precision: evalResponse.context_precision,
      context_recall: evalResponse.context_recall
    } : null,
    timestamp: new Date().toISOString()
  }
}];

